package pt.ulusofona.cd.product.controller;
import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import pt.ulusofona.cd.product.model.dto.*; import pt.ulusofona.cd.product.service.ProductService; import java.util.*;
@RestController @RequestMapping("/api/v1/products") public class ProductController {private final ProductService s; public ProductController(ProductService s){this.s=s;} @PostMapping ResponseEntity<ProductResponse> create(@Valid @RequestBody ProductRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(r));} @GetMapping List<ProductResponse> all(){return s.all();} @GetMapping("/{id}") ProductResponse one(@PathVariable UUID id){return s.one(id);} @GetMapping("/count") long count(@RequestParam UUID supplierId){return s.count(supplierId);} @PutMapping("/{id}") ProductResponse update(@PathVariable UUID id,@Valid @RequestBody ProductRequest r){return s.update(id,r);} @DeleteMapping("/{id}") ResponseEntity<Void> delete(@PathVariable UUID id){s.delete(id);return ResponseEntity.noContent().build();}}
